let grid=[],entities=[],houses=[],villages=[],effects=[],history=[],simTime=0,speed=1,paused=false,tool='land',radius=2,tab='terrain',seed='binh-minh',rngState=1,idCounter=1,mapType='islands',sounds=false,audioContext;
let cw=0,ch=0,base=1,zoom=1,panX=0,panY=0,dragging=false,lastPoint=null,lastPaint=0,selectedId=null,pointers=new Map(),pinch=null,ready=false,accumulator=0;
